// select_point(table, n, idx): the point table[idx] (idx < n), every entry read
// (constant time), as Go's p256Select: each masked by idx == j and or-ed.
select_point:
    mov rsi, qword ptr [rsp + 8]
    mov rcx, qword ptr [rsp + 16]
    mov rdx, qword ptr [rsp + 24]
    pxor xmm0, xmm0
    pxor xmm1, xmm1
    pxor xmm2, xmm2
    pxor xmm3, xmm3
    pxor xmm4, xmm4
    pxor xmm5, xmm5
    mov rax, 0
    cmp rcx, 0
    je .done
.loop:
    mov r8, rax
    xor r8, rdx
    mov r9, r8
    neg r9
    or r8, r9
    shr r8, 63
    sub r8, 1
    movq xmm15, r8
    pshufd xmm15, xmm15, 0x44
    movdqu xmm8, xmmword ptr [rsi]
    movdqu xmm9, xmmword ptr [rsi + 16]
    movdqu xmm10, xmmword ptr [rsi + 32]
    movdqu xmm11, xmmword ptr [rsi + 48]
    movdqu xmm12, xmmword ptr [rsi + 64]
    movdqu xmm13, xmmword ptr [rsi + 80]
    pand xmm8, xmm15
    pand xmm9, xmm15
    pand xmm10, xmm15
    pand xmm11, xmm15
    pand xmm12, xmm15
    pand xmm13, xmm15
    por xmm0, xmm8
    por xmm1, xmm9
    por xmm2, xmm10
    por xmm3, xmm11
    por xmm4, xmm12
    por xmm5, xmm13
    add rsi, 96
    inc rax
    cmp rax, rcx
    jne .loop
.done:
    movdqu xmmword ptr [r13], xmm0
    movdqu xmmword ptr [r13 + 16], xmm1
    movdqu xmmword ptr [r13 + 32], xmm2
    movdqu xmmword ptr [r13 + 48], xmm3
    movdqu xmmword ptr [r13 + 64], xmm4
    movdqu xmmword ptr [r13 + 80], xmm5
    ret

