    pand xmm10, xmm15
    pand xmm11, xmm15
    por xmm0, xmm8
    por xmm1, xmm9
    por xmm2, xmm10
    por xmm3, xmm11
    add rsi, 64
    inc rax
    cmp rax, rcx
    jne .loop
.done:
    movdqu xmmword ptr [r13], xmm0
    movdqu xmmword ptr [r13 + 16], xmm1
    movdqu xmmword ptr [r13 + 32], xmm2
    movdqu xmmword ptr [r13 + 48], xmm3
    ret
